const input = $json;
const payload = input.body ?? input.payload ?? input;
const value = payload?.entry?.[0]?.changes?.[0]?.value
  ?? payload?.changes?.[0]?.value
  ?? payload?.value
  ?? payload;
const message = value?.messages?.[0] ?? input.message ?? null;
const contact = value?.contacts?.[0] ?? {};
const metadata = value?.metadata ?? {};
const blockers = [];
if (!message?.id) blockers.push('EXTERNAL_MESSAGE_ID_MISSING');
if (!message?.from && !contact?.wa_id) blockers.push('SENDER_ID_MISSING');

const normalize = (text) => String(text || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
  .replace(/[^a-z0-9°\s]/g, ' ').replace(/\s+/g, ' ').trim();
const text = message?.type === 'text' ? (message?.text?.body ?? '') : '';
const normalized = normalize(text);
const services = new Set();
const evidence = [];
const ctaSignals = [];

if (normalized.includes('gostaria de solicitar um orcamento')) {
  evidence.push('CTA: solicitar orçamento'); ctaSignals.push('cta_promocao');
}
if (normalized.includes('quero um orcamento') || normalized.includes('quero orcamento')) {
  evidence.push('CTA: orçamento'); ctaSignals.push('cta_orcamento');
}
if (normalized.includes('quero um atendimento 360')) {
  services.add('plataforma_360'); evidence.push('CTA: atendimento 360'); ctaSignals.push('cta_360');
}
const cabinMention = /\bcabine de fotos?\b/.test(normalized);
const cabinNegated = /\b(nao quero|nao tenho interesse em|sem) (a )?cabine( de fotos?)?\b/.test(normalized);
if (cabinMention && !cabinNegated) { services.add('cabine_fotos'); evidence.push('palavra-chave: cabine de foto(s)'); }
const totemMention = /\btotem( de fotos?)?\b/.test(normalized);
const totemNegated = /\b(nao quero|nao tenho interesse em|sem) (o )?totem( de fotos?)?\b/.test(normalized);
if (totemMention && !totemNegated) { services.add('totem_fotos'); evidence.push('palavra-chave: totem'); }
const platformMention = /\bplataforma\b|\b360( graus|°)?\b/.test(normalized);
const platformNegated = /\b(nao quero|nao tenho interesse em|sem) (a )?plataforma\b/.test(normalized);
if (platformMention && !platformNegated) { services.add('plataforma_360'); evidence.push('palavra-chave: plataforma/360'); }

const interest = [...services].sort();
const greetingOnly = /^(oi|ola|bom dia|boa tarde|boa noite|tudo bem|oi tudo bem|ola tudo bem)$/.test(normalized);
const requiresJev = interest.length === 0 && normalized.length > 0 && !greetingOnly;
return { json: {
  accepted: blockers.length === 0, blockers,
  message_context: {
    contract_version: '1.0.0', event_type: 'message_received', channel: 'whatsapp', transport: 'meta_whatsapp',
    external_message_id: message?.id ?? null, idempotency_key: message?.id ? 'meta:' + message.id : null,
    sender_id: message?.from ?? contact?.wa_id ?? null, sender_display_name: contact?.profile?.name ?? null,
    phone_number_id: metadata?.phone_number_id ?? null, message_type: message?.type ?? null,
    text, occurred_at_unix: message?.timestamp ?? null
  },
  classification: {
    product_interest: interest, interest_type: interest.length > 1 ? 'combo' : interest.length === 1 ? 'single' : 'not_identified',
    cta_signals: [...new Set(ctaSignals)], evidence,
    next_route: interest.length > 1 ? 'COMBO_BUSINESS_RULES' : interest.length === 1 ? 'SINGLE_PRODUCT_BUSINESS_RULES' :
      requiresJev ? 'JEV_SEMANTIC_CLASSIFICATION' : 'INTRODUCTION_THEN_PRODUCT_QUESTION',
    requires_jev: requiresJev
  },
  effects: { database_write: false, whatsapp_reply: false, quote_calculation: false }
}};

const response = $json;
const answer = response?.answers?.product_interest ?? {};
const choice = answer.choice ?? null;
const confidence = Number(answer.confidence ?? 0);
const serviceMap = {
  cabine_fotos: ['cabine_fotos'],
  totem_fotos: ['totem_fotos'],
  plataforma_360: ['plataforma_360'],
  combo_cabine_plataforma: ['cabine_fotos', 'plataforma_360'],
  combo_cabine_totem: ['cabine_fotos', 'totem_fotos'],
  combo_totem_plataforma: ['totem_fotos', 'plataforma_360'],
  combo_todos: ['cabine_fotos', 'totem_fotos', 'plataforma_360']
};
const threshold = 0.8;
const productInterest = confidence >= threshold ? (serviceMap[choice] ?? []) : [];
const kind = productInterest.length > 1 ? 'combo' : productInterest.length === 1 ? 'single' : 'not_identified';
const route = kind === 'combo' ? 'COMBO_BUSINESS_RULES' :
  kind === 'single' ? 'SINGLE_PRODUCT_BUSINESS_RULES' : 'INTRODUCTION_THEN_PRODUCT_QUESTION';
return { json: {
  classification: {
    product_interest: productInterest,
    interest_type: kind,
    next_route: route,
    requires_clarification: kind === 'not_identified',
    jev_choice: choice,
    jev_confidence: confidence,
    confidence_threshold: threshold
  },
  jev: {
    id: response?.id ?? null,
    model: response?.model ?? 'typesafe/jev-1.13',
    provider: response?.provider ?? null,
    usage: response?.usage ?? null
  },
  effects: { database_write: false, whatsapp_reply: false, quote_calculation: false }
}};
